  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.container {
  width: 100%;
  max-width: 560px;
  margin-inline: auto;
  padding-inline: 1rem;
}

/* ─── Skip link ─────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  background: var(--color-primary);
  color: var(--color-primary-text);
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top 0.1s;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--color-text);
  outline-offset: 2px;
}

/* ─── Header ────────────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding-block: 1rem;
}

.logo {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-logo);
  letter-spacing: -0.01em;
}

/* ─── Main / Card ───────────────────────────────────────────────────── */
main.container {
  flex: 1;
  padding-block: 3rem;
}

.form-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 2.5rem;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.07), 0 1px 2px -1px rgb(0 0 0 / 0.07);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

.form-intro {
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
  margin-bottom: 2rem;
}

/* ─── Form fields ───────────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.375rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-marker {
  color: var(--color-error);
  margin-left: 0.125rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: none;
}

input:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgb(37 99 235 / 0.18);
}

input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgb(185 28 28 / 0.18);
}

/* ─── Helper & error text ───────────────────────────────────────────── */
.field-hint {
  font-size: 0.8125rem;
  color: var(--color-hint);
  margin-top: -0.125rem;
}

.field-error {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-error);
}

/* ─── Submit button ─────────────────────────────────────────────────── */
.btn-submit {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: var(--color-primary-text);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  align-self: flex-start;
  transition: background-color 0.15s, box-shadow 0.15s;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ─── Success panel ─────────────────────────────────────────────────── */
#success-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.75rem;
  padding-block: 1rem;
}

.success-icon {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: var(--color-success-bg);
  color: var(--color-success);
  font-size: 1.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

#success-panel h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-text);
}

#success-panel p {
  color: var(--color-text-secondary);
  font-size: 0.9375rem;
  max-width: 34ch;
}

.btn-reset {
  margin-top: 0.5rem;
  padding: 0.625rem 1.25rem;
  background: transparent;
  color: var(--color-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  font-family: inherit;
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s;
}

.btn-reset:hover {
  background: rgb(37 99 235 / 0.06);
}

.btn-reset:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ─── Footer ────────────────────────────────────────────────────────── */
.site-footer {
  padding-block: 1.25rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}

.site-footer p {
  font-size: 0.875rem;
  color: var(--color-hint);
  text-align: center;
}

/* ─── Reflow (≤ 320 px) ─────────────────────────────────────────────── */
@media (max-width: 480px) {
  .form-card {
    padding: 1.5rem 1.25rem;
  }

  .btn-submit {
    width: 100%;
    align-self: stretch;
  }
}

/* ─── Forced-colors / high-contrast ────────────────────────────────── */
@media (forced-colors: active) {
  input:focus,
  .btn-submit:focus-visible,
  .btn-reset:focus-visible {
    outline: 3px solid ButtonText;
  }

  .required-marker {
    color: Mark;
    forced-color-adjust: none;
  }
}

/* ─── Reduced motion ────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
  }
}
