  'use strict';

  const form = document.getElementById('contact-form');
  const successPanel = document.getElementById('success-panel');
  const btnReset = document.getElementById('btn-reset');
  const errorSummary = document.getElementById('form-error-summary');
  const formStatus = document.getElementById('form-success');

  // Field descriptors: id, label, validator → error message
  const FIELDS = [
    {
      id: 'full-name',
      label: 'Full name',
      errorId: 'full-name-error',
      validate: (v) => (v.trim().length > 0 ? null : 'Enter your full name.'),
    },
    {
      id: 'email',
      label: 'Email address',
      errorId: 'email-error',
      validate: (v) =>
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())
          ? null
          : 'Enter a valid email address, like name@example.com.',
    },
    {
      id: 'phone',
      label: 'Phone number',
      errorId: 'phone-error',
      optional: true,
      validate: (v) => {
        if (v.trim() === '') return null; // optional — blank is fine
        // Accept common international and North-American formats
        return /^[+\d][\d\s\-().]{6,19}$/.test(v.trim())
          ? null
          : 'Enter a valid phone number, like +1 (555) 000-0000.';
      },
    },
  ];

  /** Show an error on a field */
  function setFieldError(field, message) {
    const input = document.getElementById(field.id);
    const errorEl = document.getElementById(field.errorId);
    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = `Error: ${message}`;
    errorEl.hidden = false;
  }

  /** Clear error state on a field */
  function clearFieldError(field) {
    const input = document.getElementById(field.id);
    const errorEl = document.getElementById(field.errorId);
    input.removeAttribute('aria-invalid');
    errorEl.hidden = true;
    errorEl.textContent = '';
  }

  /** Validate a single field; returns error message or null */
  function validateField(field) {
    const input = document.getElementById(field.id);
    return field.validate(input.value);
  }

  /** Live validation — only after the field has been interacted with */
  function attachLiveValidation(field) {
    const input = document.getElementById(field.id);
    let dirty = false;

    input.addEventListener('blur', () => {
      dirty = true;
      const error = validateField(field);
      if (error) {
        setFieldError(field, error);
      } else {
        clearFieldError(field);
      }
    });

    input.addEventListener('input', () => {
      if (!dirty) return;
      const error = validateField(field);
      if (error) {
        setFieldError(field, error);
      } else {
        clearFieldError(field);
      }
    });
  }

  FIELDS.forEach(attachLiveValidation);

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Validate all fields
    const errors = [];
    FIELDS.forEach((field) => {
      const error = validateField(field);
      if (error) {
        setFieldError(field, error);
        errors.push({ field, error });
      } else {
        clearFieldError(field);
      }
    });

    if (errors.length > 0) {
      // Announce error count, then focus the first invalid field
      const noun = errors.length === 1 ? 'error' : 'errors';
      errorSummary.textContent = `${errors.length} ${noun} found. Please correct the highlighted fields.`;
      document.getElementById(errors[0].field.id).focus();
      return;
    }

    // Clear any previous error summary
    errorSummary.textContent = '';

    // Simulate submission success
    form.hidden = true;
    successPanel.hidden = false;
    formStatus.textContent = 'Your message has been sent. We\'ll be in touch within one business day.';
    // Move focus to the success heading so screen-reader users know the outcome
    const successHeading = successPanel.querySelector('h2');
    successHeading.setAttribute('tabindex', '-1');
    successHeading.focus();
  });

  // "Send another message" resets the form
  btnReset.addEventListener('click', () => {
    form.reset();
    FIELDS.forEach(clearFieldError);
    errorSummary.textContent = '';
    formStatus.textContent = '';
    successPanel.hidden = true;
    form.hidden = false;
    // Return focus to the first input
    document.getElementById(FIELDS[0].id).focus();
  });
})();
